INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM207ECZS', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $ABC$, the exterior angle at vertex $C$ measures $140^\\circ$. If $\\angle A = 65^\\circ$, what is the measure, in degrees, of $\\angle B$?', NULL, $lyceon_json$[{"key":"A","text":"$40$"},{"key":"B","text":"$65$"},{"key":"C","text":"$75$"},{"key":"D","text":"$115$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $75$. By the exterior angle theorem, an exterior angle of a triangle equals the sum of the two non-adjacent interior angles: $140 = 65 + \\angle B$, so $\\angle B = 140 - 65 = 75$. The result $40$ comes from finding the interior angle at $C$ as $180 - 140 = 40$ but stopping there instead of solving for $\\angle B$. The result $115$ comes from computing $180 - 65$, which ignores the exterior angle information entirely. The result $65$ mistakes $\\angle B$ for the same measure as $\\angle A$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20H5RP3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A data set of $20$ values has a mean of $50$ and a median of $45$. Every value in the data set is then increased by $10$. Which of the following correctly describes the new mean and new median?', NULL, $lyceon_json$[{"key":"A","text":"The new mean is $60$ and the new median is $55$."},{"key":"B","text":"The new mean is $60$ and the new median is $45$."},{"key":"C","text":"The new mean is $500$ and the new median is $450$."},{"key":"D","text":"The new mean is $50$ and the new median is $55$."}]$lyceon_json$::jsonb, 'A', NULL, E'Adding a constant to every value in a data set increases both the mean and the median by that constant. The new mean is $50 + 10 = 60$ and the new median is $45 + 10 = 55$. The choice stating the median remains $45$ incorrectly assumes the median is unaffected by shifting all values. The choice with $500$ and $450$ incorrectly multiplies each measure by $10$ instead of adding $10$. The choice stating the mean remains $50$ while only the median changes incorrectly applies the shift to the median alone.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2137FFF', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'If $5x - 10 = 20$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$6$"},{"key":"C","text":"$-6$"},{"key":"D","text":"$30$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $6$. Adding $10$ to both sides of $5x - 10 = 20$ gives $5x = 30$, and dividing both sides by $5$ gives $x = 6$. The value $2$ results from dividing $20$ by $10$ rather than solving the equation correctly. The value $-6$ comes from a sign error when dividing $30$ by $5$. The value $30$ is the intermediate result $5x = 30$ before dividing by $5$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21GW2U0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A factory produces widgets at a rate of $180$ widgets per hour. Due to a machine upgrade, the production rate increases by $\\frac{1}{3}$. At the new rate, how many minutes does it take to produce $400$ widgets?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '100', ARRAY['100'], E'The original rate is $180$ widgets per hour. An increase of $\\frac{1}{3}$ means the new rate is $180 + \\frac{1}{3}(180) = 180 + 60 = 240$ widgets per hour, which is $\\frac{240}{60} = 4$ widgets per minute. To produce $400$ widgets at $4$ widgets per minute: $\\frac{400}{4} = 100$ minutes.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21O38CM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A standard deck of $52$ playing cards contains $4$ suits of $13$ cards each. Two cards are drawn at random without replacement. Given that the first card drawn is a king, what is the probability that the second card drawn is also a king?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{3}{51}$"},{"key":"B","text":"$\\frac{4}{52}$"},{"key":"C","text":"$\\frac{3}{52}$"},{"key":"D","text":"$\\frac{1}{13}$"}]$lyceon_json$::jsonb, 'A', NULL, E'After one king is drawn, there are $3$ kings remaining among $51$ cards, so the conditional probability is $\\frac{3}{51}$. The answer $\\frac{4}{52}$ ignores the condition that a king was already drawn, treating the draws as independent. The answer $\\frac{3}{52}$ correctly reduces the number of kings to $3$ but fails to reduce the total number of cards to $51$. The answer $\\frac{1}{13}$ is the unconditional probability of drawing any single king from a full deck and does not account for the without-replacement condition.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22BBT2D', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A car rental company charges a flat fee of $\\$20$ plus $\\$0.25$ per mile driven. If a customer was charged a total of $\\$50$, how many miles did the customer drive?', NULL, $lyceon_json$[{"key":"A","text":"$120$"},{"key":"B","text":"$30$"},{"key":"C","text":"$200$"},{"key":"D","text":"$280$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $120$ miles. The total charge can be modeled as $f(m) = 20 + 0.25m$, where $m$ is the number of miles. Setting $20 + 0.25m = 50$ and subtracting $20$ from both sides gives $0.25m = 30$. Dividing both sides by $0.25$ gives $m = 120$. The value $30$ comes from computing $50 - 20 = 30$ but stopping before dividing by the per-mile rate. The value $200$ results from dividing the total charge $50$ by $0.25$ without first subtracting the flat fee. The value $280$ results from an arithmetic error of adding the flat fee to the total before dividing: $\\frac{50 + 20}{0.25} = 280$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24A6O22', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A recipe calls for $2$ cups of flour to make $24$ cookies. How many cups of flour are needed to make $60$ cookies?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$4$"},{"key":"C","text":"$5$"},{"key":"D","text":"$6$"}]$lyceon_json$::jsonb, 'C', NULL, E'The ratio of flour to cookies is $\\frac{2}{24} = \\frac{1}{12}$, meaning $\\frac{1}{12}$ cup of flour per cookie. For $60$ cookies: $60 \\times \\frac{1}{12} = 5$ cups. The answer $3$ results from an arithmetic error in computing the scale factor. The answer $4$ comes from incorrectly setting up the proportion. The answer $6$ results from mistakenly tripling the original flour amount without using the correct ratio.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24SXBFM', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'The function $g$ is defined by $g(x) = ax + b$, where $a$ and $b$ are constants. If $g(3) = 7$ and $g(-1) = -5$, what is the value of $g(5)$?', NULL, $lyceon_json$[{"key":"A","text":"$10$"},{"key":"B","text":"$13$"},{"key":"C","text":"$17$"},{"key":"D","text":"$19$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $13$. From $g(3) = 7$ and $g(-1) = -5$, the slope is $a = \\frac{7 - (-5)}{3 - (-1)} = \\frac{12}{4} = 3$. Substituting into $g(3) = 3(3) + b = 7$ gives $b = -2$, so $g(x) = 3x - 2$. Therefore $g(5) = 3(5) - 2 = 13$. The value $10$ results from adding only one slope increment to $g(3)$: $7 + 3 = 10$, rather than two increments for the change from $x = 3$ to $x = 5$. The value $17$ comes from a sign error when computing $b$: using $b = 2$ instead of $b = -2$, giving $g(5) = 15 + 2 = 17$. The value $19$ results from incorrectly computing the slope as $\\frac{12}{2} = 6$ by using $3 + (-1) = 2$ in the denominator instead of $3 - (-1) = 4$, leading to $a = 6$, $b = -11$, and $g(5) = 19$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM251LACS', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular garden has a length of $15$ feet and a width of $8$ feet. What is the perimeter, in feet, of the garden?', NULL, $lyceon_json$[{"key":"A","text":"$23$"},{"key":"B","text":"$38$"},{"key":"C","text":"$46$"},{"key":"D","text":"$120$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $46$. The perimeter of a rectangle is $P = 2(l + w) = 2(15 + 8) = 2(23) = 46$. The result $23$ comes from adding $15 + 8$ but not multiplying by $2$, computing only half the perimeter. The result $38$ comes from doubling only one dimension: $2(15) + 8 = 38$. The result $120$ comes from computing the area $15 \\times 8 = 120$ instead of the perimeter.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM253N95H', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A student has a budget of at most $\\$200$. They have already spent $\\$45$ on books and plan to buy notebooks that cost $\\$8$ each. Which inequality represents the number of notebooks, $n$, the student can buy?', NULL, $lyceon_json$[{"key":"A","text":"$45 + 8n \\leq 200$"},{"key":"B","text":"$45 + 8n \\geq 200$"},{"key":"C","text":"$8n \\leq 200$"},{"key":"D","text":"$45n + 8 \\leq 200$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total spending is the $\\$45$ already spent plus $\\$8$ per notebook, giving $45 + 8n$. Since the budget is at most $\\$200$, the inequality is $45 + 8n \\leq 200$. The choice $45 + 8n \\geq 200$ incorrectly uses a greater-than-or-equal sign, which would mean spending at least $\\$200$ rather than at most. The choice $8n \\leq 200$ omits the $\\$45$ already spent on books. The choice $45n + 8 \\leq 200$ swaps the cost per notebook and the fixed cost, treating $\\$45$ as the per-item cost and $\\$8$ as the fixed amount.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25HC3TW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A car travels $150$ miles using $5$ gallons of gasoline. At the same rate, how many gallons of gasoline would the car need to travel $420$ miles?', NULL, $lyceon_json$[{"key":"A","text":"$12$"},{"key":"B","text":"$14$"},{"key":"C","text":"$15$"},{"key":"D","text":"$84$"}]$lyceon_json$::jsonb, 'B', NULL, E'The car''s rate is $\\frac{150}{5} = 30$ miles per gallon. To travel $420$ miles, the car needs $\\frac{420}{30} = 14$ gallons. The answer $12$ results from a computational error such as dividing $420$ by $35$. The answer $15$ comes from incorrectly multiplying the original $5$ gallons by $3$ without properly accounting for the mileage ratio. The answer $84$ results from dividing $420$ by $5$ directly, ignoring the miles-per-gallon rate.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25PX02T', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which value of $x$ satisfies the inequality $3x + 7 > 22$?', NULL, $lyceon_json$[{"key":"A","text":"$x > 5$"},{"key":"B","text":"$x < 5$"},{"key":"C","text":"$x > 15$"},{"key":"D","text":"$x > \\frac{29}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Subtract $7$ from both sides of $3x + 7 > 22$ to get $3x > 15$, then divide both sides by $3$ to obtain $x > 5$. The choice $x < 5$ results from reversing the inequality sign when dividing by a positive number, which is a sign error. The choice $x > 15$ comes from subtracting $7$ correctly but failing to divide by $3$, stopping at an intermediate step. The choice $x > \\frac{29}{3}$ results from adding $7$ to $22$ instead of subtracting it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25XAIDB', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $2x + y = 8$?', NULL, $lyceon_json$[{"key":"A","text":"$-2$"},{"key":"B","text":"$4$"},{"key":"C","text":"$8$"},{"key":"D","text":"$-8$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $8$. To find the $y$-intercept, set $x = 0$ in $2x + y = 8$, which gives $y = 8$. The value $-2$ confuses the slope with the $y$-intercept; rewriting as $y = -2x + 8$ shows the slope is $-2$, not the intercept. The value $4$ results from incorrectly dividing $8$ by the coefficient $2$. The value $-8$ comes from a sign error when identifying the constant term.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26ZJQEX', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A scatterplot shows the relationship between hours studied and test scores for $15$ students. The line of best fit is $y = 8x + 42$, where $x$ is the number of hours studied and $y$ is the test score. One student studied for $6$ hours and scored $95$. What is the residual for this student?', NULL, $lyceon_json$[{"key":"A","text":"$-5$"},{"key":"B","text":"$3$"},{"key":"C","text":"$5$"},{"key":"D","text":"$90$"}]$lyceon_json$::jsonb, 'C', NULL, E'The predicted score for $x = 6$ is $y = 8(6) + 42 = 48 + 42 = 90$. The residual is the actual value minus the predicted value: $95 - 90 = 5$. The answer $-5$ results from reversing the subtraction order (predicted minus actual instead of actual minus predicted). The answer $3$ comes from an arithmetic error in computing the predicted value. The answer $90$ gives the predicted value itself rather than the residual.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM274B6D7', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'If $x^2 + 4x = 21$, what is the positive value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'Rearrange the equation to standard form: $x^2 + 4x - 21 = 0$. Factor: $(x + 7)(x - 3) = 0$, giving $x = -7$ or $x = 3$. Since the question asks for the positive value, the answer is $3$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28SCW7L', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of $500$ households and finds that $34\\%$ use solar panels. The margin of error is $3$ percentage points at a $95\\%$ confidence level. Which of the following conclusions is best supported by the data?', NULL, $lyceon_json$[{"key":"A","text":"At least $34\\%$ of all households use solar panels."},{"key":"B","text":"It is likely that between $31\\%$ and $37\\%$ of all households use solar panels."},{"key":"C","text":"Exactly $95\\%$ of all households fall within the margin of error."},{"key":"D","text":"If the sample size were increased to $1{,}000$, the sample percentage would be $34\\%$."}]$lyceon_json$::jsonb, 'B', NULL, E'With a sample proportion of $34\\%$ and a margin of error of $3$ percentage points, the $95\\%$ confidence interval for the population proportion is $34\\% \\pm 3\\%$, or $31\\%$ to $37\\%$. The choice claiming at least $34\\%$ incorrectly treats the sample proportion as a lower bound for the population parameter. The choice about $95\\%$ of all households misinterprets the confidence level: $95\\%$ refers to the reliability of the interval estimation method, not to a percentage of households. The choice about increasing the sample size confuses sample size with sample proportion; a larger sample may yield a different percentage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28Y4RHS', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'A line passes through the points $(1, 3)$ and $(4, 9)$. Which of the following is the equation of this line?', NULL, $lyceon_json$[{"key":"A","text":"$y = 2x + 1$"},{"key":"B","text":"$y = 2x - 1$"},{"key":"C","text":"$y = 3x$"},{"key":"D","text":"$y = \\frac{1}{2}x + \\frac{5}{2}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $y = 2x + 1$. The slope is $\\frac{9 - 3}{4 - 1} = \\frac{6}{3} = 2$. Using point-slope form with $(1, 3)$: $y - 3 = 2(x - 1)$, which simplifies to $y = 2x + 1$. Substituting both points confirms: $2(1) + 1 = 3$ and $2(4) + 1 = 9$. The equation $y = 2x - 1$ has the correct slope but a sign error in computing the $y$-intercept. The equation $y = 3x$ results from an arithmetic error in the slope calculation. The equation $y = \\frac{1}{2}x + \\frac{5}{2}$ uses the reciprocal of the slope, confusing $\\frac{\\Delta x}{\\Delta y}$ with $\\frac{\\Delta y}{\\Delta x}$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A7KU63', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'If $a = 2x + 1$, which of the following is equivalent to $\\frac{a^2 - 4a + 4}{a - 2}$?', NULL, $lyceon_json$[{"key":"A","text":"$2x + 3$"},{"key":"B","text":"$2x - 1$"},{"key":"C","text":"$4x^2 - 1$"},{"key":"D","text":"$2x + 1$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $2x - 1$. First, recognize that $a^2 - 4a + 4 = (a - 2)^2$. Dividing by $(a - 2)$ gives $a - 2$. Substituting $a = 2x + 1$ yields $(2x + 1) - 2 = 2x - 1$. The expression $2x + 3$ results from a sign error, computing $a + 2$ instead of $a - 2$ after simplification. The expression $4x^2 - 1$ arises from incorrectly interpreting the original expression as a difference of squares $(a - 2)(a + 2)$ rather than a perfect square trinomial. The expression $2x + 1$ comes from stopping at $a$ without subtracting $2$.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ACEODE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A researcher finds that students who eat breakfast score higher on tests than students who skip breakfast. The study tracked students'' existing habits without any intervention. What type of study is this?', NULL, $lyceon_json$[{"key":"A","text":"A controlled experiment"},{"key":"B","text":"An observational study"},{"key":"C","text":"A sample survey"},{"key":"D","text":"A census"}]$lyceon_json$::jsonb, 'B', NULL, E'Because the researcher observed students'' existing breakfast habits without assigning them to eat or skip breakfast, this is an observational study. The choice stating a controlled experiment is incorrect because no treatment was imposed on the participants; a controlled experiment would require randomly assigning students to breakfast or no-breakfast groups. A sample survey collects self-reported data at a point in time but does not track outcomes like test scores alongside behaviors. A census involves collecting data from every member of a population, which is not described here.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AT45OH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'The mean of six numbers is $15$. When a seventh number is added, the mean becomes $18$. What is the seventh number?', NULL, $lyceon_json$[{"key":"A","text":"$21$"},{"key":"B","text":"$33$"},{"key":"C","text":"$36$"},{"key":"D","text":"$126$"}]$lyceon_json$::jsonb, 'C', NULL, E'The sum of the original six numbers is $6 \\times 15 = 90$. With the seventh number added, the total sum must be $7 \\times 18 = 126$. Therefore, the seventh number is $126 - 90 = 36$. The answer $21$ comes from adding the difference in means to the new mean ($18 + 3 = 21$), an incomplete approach. The answer $33$ results from an arithmetic slip in the subtraction step. The answer $126$ mistakes the total sum of all seven numbers for the seventh number itself.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BMZ6FH', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'$$kx + 4y = 12$$ $$3x + 2y = 5$$ For what value of $k$ does the system of equations above have no solution?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$4$"},{"key":"C","text":"$6$"},{"key":"D","text":"$12$"}]$lyceon_json$::jsonb, 'C', NULL, E'A system of two linear equations has no solution when the lines are parallel but not identical, meaning the ratios of corresponding coefficients are equal but differ from the ratio of constants. Setting $\\frac{k}{3} = \\frac{4}{2}$ gives $\\frac{k}{3} = 2$, so $k = 6$. Checking the constant ratio: $\\frac{12}{5} = 2.4 \\neq 2$, confirming the lines are parallel and distinct. The value $2$ results from incorrectly equating $k$ to the ratio $\\frac{4}{2}$ directly rather than solving the proportion $\\frac{k}{3} = \\frac{4}{2}$. The value $4$ comes from matching $k$ to the $y$-coefficient of the first equation without forming the correct ratio. The value $12$ results from computing $3 \\times 4 = 12$, multiplying the coefficients of $x$ and $y$ from different equations instead of using the correct proportionality condition.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C2ZX5E', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A data set contains the values $3, 5, 7, 7, 8$. What is the median of this data set?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$6$"},{"key":"C","text":"$7$"},{"key":"D","text":"$8$"}]$lyceon_json$::jsonb, 'C', NULL, E'When the values are arranged in order ($3, 5, 7, 7, 8$), the median is the middle value. With $5$ data points, the middle value is the $3$rd, which is $7$. The answer $5$ results from selecting the second value instead of the middle value. The answer $6$ comes from averaging $5$ and $7$ as if the data set had an even number of values. The answer $8$ results from choosing the wrong position in the ordered list.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C8B8U1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'grid_in', E'A store raises the price of an item by $20\\%$. Later, the store offers a $20\\%$ discount on the new price. If the final price is $\\$57.60$, what was the original price of the item, in dollars?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '60', ARRAY['60'], E'Let the original price be $p$. After a $20\\%$ increase, the price becomes $1.20p$. After a $20\\%$ discount on the new price, the final price is $0.80 \\times 1.20p = 0.96p$. Setting $0.96p = 57.60$ gives $p = \\frac{57.60}{0.96} = 60$. A common error is assuming the $20\\%$ increase and $20\\%$ decrease cancel out, yielding $\\$57.60$ as the original price. Another error is computing $\\frac{57.60}{1.00}$ instead of $\\frac{57.60}{0.96}$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FSD3NL', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two angles of a triangle measure $50^\\circ$ and $70^\\circ$. What is the measure, in degrees, of the third angle?', NULL, $lyceon_json$[{"key":"A","text":"$40$"},{"key":"B","text":"$60$"},{"key":"C","text":"$80$"},{"key":"D","text":"$120$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $60$. The sum of the interior angles of a triangle is $180^\\circ$. Subtracting the two known angles gives $180 - 50 - 70 = 60$. The result $80$ comes from incorrectly adding $50 + 70 = 100$ instead of $120$, then computing $180 - 100$. The result $120$ comes from adding $50 + 70$ but stopping without subtracting from $180$. The result $40$ comes from mistakenly using one angle twice, such as $180 - 70 - 70$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GL735M', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'How many distinct real solutions does the following system of equations have?$$y = x^2 - 4x + 5$$$$y = 2x - 3$$', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $2$. Set the expressions equal: $x^2 - 4x + 5 = 2x - 3$, which simplifies to $x^2 - 6x + 8 = 0$. Factor: $(x - 2)(x - 4) = 0$, giving $x = 2$ and $x = 4$. Each $x$-value yields a unique $y$-value, producing two distinct intersection points: $(2, 1)$ and $(4, 5)$. The answer $0$ reflects a misconception that a parabola and a line cannot intersect. The answer $1$ results from incorrectly concluding the discriminant equals zero. The answer $4$ comes from adding the two $x$-values rather than counting the number of solutions.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I7MXKR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A shirt originally costs $\\$40$. If the shirt is on sale for $25\\%$ off, what is the sale price?', NULL, $lyceon_json$[{"key":"A","text":"$\\$10$"},{"key":"B","text":"$\\$15$"},{"key":"C","text":"$\\$25$"},{"key":"D","text":"$\\$30$"}]$lyceon_json$::jsonb, 'D', NULL, E'The discount is $25\\%$ of $\\$40$, which is $0.25 \\times 40 = \\$10$. The sale price is $\\$40 - \\$10 = \\$30$. The answer $\\$10$ gives only the discount amount rather than the final sale price. The answer $\\$15$ results from a computational error in applying the percentage. The answer $\\$25$ comes from confusing the percentage with a dollar amount or misapplying the discount formula, such as computing $\\frac{40}{1.6}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IC03J8', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A line of best fit for a scatterplot is given by $y = 2x + 5$. According to this model, what is the predicted value of $y$ when $x = 10$?', NULL, $lyceon_json$[{"key":"A","text":"$15$"},{"key":"B","text":"$20$"},{"key":"C","text":"$25$"},{"key":"D","text":"$30$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $x = 10$ into the equation $y = 2x + 5$ gives $y = 2(10) + 5 = 20 + 5 = 25$. The answer $15$ comes from adding $10 + 5$ and ignoring the coefficient of $x$. The answer $20$ results from computing $2(10)$ but forgetting to add the constant $5$. The answer $30$ comes from misreading the slope as $3$ or another error in interpreting the equation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J1LLJT', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $h(x) = -2x^2 + 12x - 10$ can be rewritten in the form $h(x) = -2(x - p)^2 + q$, where $p$ and $q$ are constants. What is the value of $q$?', NULL, $lyceon_json$[{"key":"A","text":"$-10$"},{"key":"B","text":"$8$"},{"key":"C","text":"$18$"},{"key":"D","text":"$-8$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $8$. Factor $-2$ from the quadratic and linear terms: $h(x) = -2(x^2 - 6x) - 10$. Complete the square inside the parentheses: $x^2 - 6x = (x - 3)^2 - 9$. Substitute back: $h(x) = -2((x - 3)^2 - 9) - 10 = -2(x - 3)^2 + 18 - 10 = -2(x - 3)^2 + 8$. Therefore $q = 8$. The value $-10$ comes from reading the original constant term without completing the square. The value $18$ results from computing $-2(-9) = 18$ but forgetting to subtract $10$. The value $-8$ arises from a sign error when distributing $-2$ across $-9$.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J7QPQG', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $8$. What is the circumference of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$4\\pi$"},{"key":"B","text":"$8\\pi$"},{"key":"C","text":"$16\\pi$"},{"key":"D","text":"$64\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $8\\pi$. The circumference of a circle is $C = \\pi d$, so $C = \\pi(8) = 8\\pi$. The result $4\\pi$ comes from using the radius $r = 4$ but applying $\\pi r$ instead of $2\\pi r$, computing only half the circumference. The result $16\\pi$ comes from computing the area $\\pi r^2 = \\pi(4^2) = 16\\pi$ instead of the circumference. The result $64\\pi$ comes from applying $\\pi d^2 = \\pi(64)$, squaring the diameter incorrectly.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JUKFAR', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'If $\\frac{2x + 1}{3} = 5$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$7$"},{"key":"C","text":"$8$"},{"key":"D","text":"$-7$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $7$. Multiplying both sides by $3$ gives $2x + 1 = 15$. Subtracting $1$ from both sides gives $2x = 14$, and dividing by $2$ gives $x = 7$. The value $2$ results from computing $\\frac{5 - 1}{2}$ without first multiplying by $3$, skipping a required step. The value $8$ comes from adding $1$ to $15$ instead of subtracting, yielding $2x = 16$ and $x = 8$. The value $-7$ results from a sign error in the final division.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K3G065', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'If $-5 < 3(2x - 1) - 4x \\leq 7$, what is the greatest integer value of $x$ that satisfies this compound inequality?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'First distribute and simplify the middle expression: $3(2x - 1) - 4x = 6x - 3 - 4x = 2x - 3$. The compound inequality becomes $-5 < 2x - 3 \\leq 7$. Adding $3$ to all three parts gives $-2 < 2x \\leq 10$. Dividing all parts by $2$ yields $-1 < x \\leq 5$. Since $x$ must be at most $5$ and strictly greater than $-1$, the possible integer values are $0, 1, 2, 3, 4, 5$. The greatest integer value is $5$. A common error is mishandling the strict inequality on the left and including $-1$, or failing to distribute the $3$ correctly before combining like terms.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KDE2ME', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $200$ voters in a city found that $58\\%$ support a proposed park renovation. The margin of error for the survey is $4$ percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $58\\%$ of all voters in the city support the renovation."},{"key":"B","text":"Between $54\\%$ and $62\\%$ of the sampled voters support the renovation."},{"key":"C","text":"It is plausible that the percentage of all voters in the city who support the renovation is between $54\\%$ and $62\\%$."},{"key":"D","text":"If another sample is taken, exactly $58\\%$ will again support the renovation."}]$lyceon_json$::jsonb, 'C', NULL, E'A margin of error of $4$ percentage points means the plausible range for the true population percentage is $58\\% \\pm 4\\%$, or between $54\\%$ and $62\\%$. The choice stating exactly $58\\%$ of all voters support the renovation treats the sample statistic as the exact population parameter, ignoring sampling variability. The choice about the sampled voters misapplies the interval to the sample rather than the population; the sample result is already known. The choice claiming another sample will yield exactly $58\\%$ confuses a sample estimate with a fixed value, ignoring the natural variation between samples.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L6IGPA', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In a right triangle, one acute angle measures $30^\\circ$ and the side opposite this angle has length $7$. What is the length of the hypotenuse?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{2}$"},{"key":"B","text":"$\\frac{7\\sqrt{3}}{3}$"},{"key":"C","text":"$7\\sqrt{3}$"},{"key":"D","text":"$14$"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct answer is $14$. Using $\\sin(30^\\circ) = \\frac{\\text{opposite}}{\\text{hypotenuse}}$, we get $\\frac{1}{2} = \\frac{7}{h}$, so $h = 14$. The result $\\frac{7}{2}$ comes from multiplying $7 \\times \\sin(30^\\circ) = 7 \\times \\frac{1}{2}$ instead of dividing. The result $\\frac{7\\sqrt{3}}{3}$ comes from using $\\tan(60^\\circ) = \\sqrt{3}$ and computing $\\frac{7}{\\sqrt{3}}$, which confuses the trigonometric ratio needed. The result $7\\sqrt{3}$ gives the length of the adjacent side, not the hypotenuse.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LO24XV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A university observes that students who participate in study groups have higher GPAs than students who study alone. A newspaper reports this finding with the headline: "Study groups cause higher grades." Which of the following is the most valid criticism of this headline?', NULL, $lyceon_json$[{"key":"A","text":"The sample size of the university study was too small to detect a difference."},{"key":"B","text":"The study was observational, so confounding variables may explain the association rather than a causal effect of study groups."},{"key":"C","text":"The newspaper should have reported the exact GPA difference between the two groups."},{"key":"D","text":"Only a census of all university students could determine whether study groups cause higher grades."}]$lyceon_json$::jsonb, 'B', NULL, E'The university study is observational: students self-selected into study groups rather than being randomly assigned. Confounding variables — such as motivation, prior academic ability, or time management skills — could explain the higher GPAs without study groups being the cause. The headline''s causal claim is therefore unsupported. The criticism about sample size is not established by the problem; nothing indicates the sample was too small. The suggestion that the newspaper should report exact GPA differences addresses reporting detail, not the fundamental flaw in claiming causation from an observational finding. The claim that only a census could determine causation is incorrect; a well-designed randomized experiment with a sample can establish causation — a census is neither necessary nor sufficient for causal inference.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N5ANKQ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $g$ is defined by $g(x) = 2(x - 3)^2 + 5$. What is the minimum value of $g(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$-3$"},{"key":"B","text":"$3$"},{"key":"C","text":"$5$"},{"key":"D","text":"$23$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $5$. The function $g(x) = 2(x - 3)^2 + 5$ is in vertex form $a(x - h)^2 + k$ with $a = 2 > 0$, so it opens upward and has a minimum at the vertex. The minimum value is $k = 5$, occurring when $x = 3$. The value $-3$ results from a sign error, taking the opposite of the $h$-value in $(x - 3)$. The value $3$ comes from reporting the $x$-coordinate of the vertex rather than the minimum output value. The value $23$ results from evaluating $g(0) = 2(9) + 5 = 23$, substituting an arbitrary input instead of identifying the vertex.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NE4ULM', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'$$x + y = 7$$ $$x - y = 3$$ What is the value of $x$ in the system of equations above?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$3$"},{"key":"C","text":"$5$"},{"key":"D","text":"$10$"}]$lyceon_json$::jsonb, 'C', NULL, E'Adding the two equations eliminates $y$: $(x + y) + (x - y) = 7 + 3$, which simplifies to $2x = 10$, so $x = 5$. The value $2$ is the value of $y$, not $x$, found by substituting $x = 5$ back into the first equation. The value $3$ comes from confusing the constant in the second equation with the value of $x$. The value $10$ is the sum $2x$ before dividing by $2$, an incomplete final step.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NWBCFI', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = x^2 + 3$. What is the value of $f(4)$?', NULL, $lyceon_json$[{"key":"A","text":"$19$"},{"key":"B","text":"$7$"},{"key":"C","text":"$11$"},{"key":"D","text":"$16$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $19$. Substitute $x = 4$ into the function: $f(4) = 4^2 + 3 = 16 + 3 = 19$. The value $7$ results from computing $4 + 3$ rather than $4^2 + 3$, confusing squaring with the identity. The value $11$ comes from computing $2(4) + 3$, treating the exponent as a coefficient. The value $16$ results from computing $4^2$ but omitting the $+3$ term.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PG2509', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A cylinder has a radius of $4$ cm and a height of $9$ cm. What is the volume of the cylinder?', NULL, $lyceon_json$[{"key":"A","text":"$36\\pi$"},{"key":"B","text":"$72\\pi$"},{"key":"C","text":"$144\\pi$"},{"key":"D","text":"$288\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $144\\pi$. The volume of a cylinder is $V = \\pi r^2 h = \\pi(4^2)(9) = \\pi(16)(9) = 144\\pi$. The result $36\\pi$ comes from using $\\pi r h = \\pi(4)(9) = 36\\pi$, omitting the squaring of the radius. The result $72\\pi$ comes from applying the lateral surface area formula $2\\pi r h = 2\\pi(4)(9) = 72\\pi$ instead of the volume formula. The result $288\\pi$ comes from using $2\\pi r^2 h = 2\\pi(16)(9) = 288\\pi$, incorrectly doubling the volume formula.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QIF7FG', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $3(2x + 4) - 2(x - 1)$?', NULL, $lyceon_json$[{"key":"A","text":"$4x + 14$"},{"key":"B","text":"$4x + 10$"},{"key":"C","text":"$4x + 12$"},{"key":"D","text":"$8x + 14$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $4x + 14$. Distribute: $3(2x + 4) = 6x + 12$ and $-2(x - 1) = -2x + 2$. Combining gives $6x - 2x + 12 + 2 = 4x + 14$. The expression $4x + 10$ results from a sign error when distributing the $-2$ across $-1$, yielding $-2$ instead of $+2$. The expression $4x + 12$ comes from omitting the $-2(-1) = +2$ term entirely. The expression $8x + 14$ results from failing to subtract $2x$ from $6x$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RSTUOG', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, one leg has length $5$ and the hypotenuse has length $13$. What is the length of the other leg?', NULL, $lyceon_json$[{"key":"A","text":"$8$"},{"key":"B","text":"$12$"},{"key":"C","text":"$\\sqrt{194}$"},{"key":"D","text":"$18$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $12$. By the Pythagorean theorem, $5^2 + b^2 = 13^2$, so $25 + b^2 = 169$, giving $b^2 = 144$ and $b = 12$. The result $8$ comes from subtracting $13 - 5$, which confuses the Pythagorean theorem with simple subtraction. The result $\\sqrt{194}$ comes from adding $5^2 + 13^2 = 194$ instead of subtracting. The result $18$ comes from adding $5 + 13$, treating the problem as a sum rather than applying the Pythagorean theorem.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T97AYG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'Two independent random samples are taken from the same population. Sample A consists of $100$ people and finds that $40\\%$ support a policy. Sample B consists of $900$ people and finds that $44\\%$ support the same policy. Which of the following statements is true?', NULL, $lyceon_json$[{"key":"A","text":"Sample A's result is more reliable because it was collected first."},{"key":"B","text":"The two samples prove that support is increasing over time."},{"key":"C","text":"Sample B's estimate is likely to have a smaller margin of error than Sample A's estimate."},{"key":"D","text":"The true population proportion must be between $40\\%$ and $44\\%$."}]$lyceon_json$::jsonb, 'C', NULL, E'The margin of error of a sample proportion is inversely related to the square root of the sample size. Since Sample B has $900$ respondents compared to Sample A''s $100$, Sample B will have a substantially smaller margin of error, making its estimate more precise. The claim that Sample A is more reliable because it was collected first has no statistical basis; collection order does not affect reliability. The claim that support is increasing over time is unfounded because the problem states the samples are independent and from the same population — any difference could be due to sampling variability. The claim that the true proportion must lie between $40\\%$ and $44\\%$ is not guaranteed; both are estimates subject to their own margins of error, and the true value could fall outside this range.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TFYHNI', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $PQR$, point $S$ lies on side $\\overline{QR}$ such that $\\overline{PS}$ bisects $\\angle QPR$. If $\\angle PQR = 50^\\circ$ and $\\angle PRQ = 70^\\circ$, what is the measure, in degrees, of $\\angle PSR$?', NULL, $lyceon_json$[{"key":"A","text":"$60$"},{"key":"B","text":"$80$"},{"key":"C","text":"$90$"},{"key":"D","text":"$100$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $80$. First, find $\\angle QPR = 180 - 50 - 70 = 60^\\circ$. Since $\\overline{PS}$ bisects $\\angle QPR$, we have $\\angle SPR = 30^\\circ$. In triangle $PSR$, the angle sum gives $\\angle PSR = 180 - 30 - 70 = 80$. The result $60$ comes from finding $\\angle QPR$ but stopping without completing the calculation in triangle $PSR$. The result $90$ reflects the misconception that an angle bisector always creates a right angle with the opposite side. The result $100$ comes from using $\\angle PQR = 50$ instead of $\\angle PRQ = 70$ in triangle $PSR$, yielding $180 - 30 - 50 = 100$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TJ3GSC', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'In right triangle $DEF$ with the right angle at $F$, $\\tan(D) = \\frac{3}{4}$. If $DF = 12$, what is the length of $DE$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '15', ARRAY['15'], E'The correct answer is $15$. Since the right angle is at $F$, side $DF$ is adjacent to angle $D$ and side $EF$ is opposite angle $D$. Using $\\tan(D) = \\frac{EF}{DF} = \\frac{3}{4}$, we find $EF = \\frac{3}{4} \\times 12 = 9$. The hypotenuse $DE = \\sqrt{DF^2 + EF^2} = \\sqrt{144 + 81} = \\sqrt{225} = 15$. A common error is computing $EF = \\frac{4}{3} \\times 12 = 16$ by inverting the tangent ratio, which gives $DE = 20$. Another error is finding $EF = 9$ but reporting it as the answer instead of computing the hypotenuse.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UTK8LJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'In a class of $30$ students, $18$ study Spanish, $12$ study French, and $5$ study both Spanish and French. If a student is selected at random and is known to study Spanish, what is the probability that this student also studies French?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{5}{30}$"},{"key":"B","text":"$\\frac{5}{12}$"},{"key":"C","text":"$\\frac{5}{18}$"},{"key":"D","text":"$\\frac{12}{30}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The conditional probability of studying French given that the student studies Spanish is $P(\\text{French} \\mid \\text{Spanish}) = \\frac{P(\\text{French and Spanish})}{P(\\text{Spanish})} = \\frac{5/30}{18/30} = \\frac{5}{18}$. The answer $\\frac{5}{30}$ uses the total class size as the denominator instead of restricting to Spanish students, computing the unconditional probability of studying both languages. The answer $\\frac{5}{12}$ incorrectly conditions on French students rather than Spanish students. The answer $\\frac{12}{30}$ gives the unconditional probability of studying French, ignoring the given condition entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VBQOFU', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'A function is defined by $f(x) = 3x - 4$. What is the value of $f(2)$?', NULL, $lyceon_json$[{"key":"A","text":"$-2$"},{"key":"B","text":"$2$"},{"key":"C","text":"$10$"},{"key":"D","text":"$6$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $2$. Substituting $x = 2$ into $f(x) = 3x - 4$ gives $f(2) = 3(2) - 4 = 6 - 4 = 2$. The value $-2$ results from a sign error, such as computing $4 - 6$ instead of $6 - 4$. The value $10$ comes from adding $4$ instead of subtracting, giving $6 + 4 = 10$. The value $6$ is the intermediate product $3(2) = 6$ before subtracting $4$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VIV02J', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'$$3x + 2y = 19$$ $$x - y = 3$$ What is the value of $x + y$ for the solution $(x, y)$ of the system of equations above?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'From the second equation, $x = y + 3$. Substituting into the first equation gives $3(y + 3) + 2y = 19$, which simplifies to $3y + 9 + 2y = 19$, then $5y = 10$, so $y = 2$. Substituting back, $x = 2 + 3 = 5$. Therefore $x + y = 5 + 2 = 7$. A common error is to report only $x = 5$ or only $y = 2$ instead of computing their sum. Another error is to misapply the substitution by forgetting to distribute the $3$ across the parentheses.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WBN9ZR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'After a $20\\%$ discount, the price of a laptop is $\\$680$. What was the original price of the laptop?', NULL, $lyceon_json$[{"key":"A","text":"$\\$544$"},{"key":"B","text":"$\\$800$"},{"key":"C","text":"$\\$816$"},{"key":"D","text":"$\\$850$"}]$lyceon_json$::jsonb, 'D', NULL, E'If the original price is $p$, then after a $20\\%$ discount the price is $0.80p = 680$. Solving gives $p = \\frac{680}{0.80} = 850$. The answer $\\$544$ results from applying a further $20\\%$ reduction to $\\$680$ (computing $680 \\times 0.80$), reversing the direction of the calculation. The answer $\\$800$ comes from incorrectly adding $20\\%$ of a wrong base to $\\$680$. The answer $\\$816$ results from computing $680 \\times 1.20$, which incorrectly adds $20\\%$ to the discounted price rather than dividing by $0.80$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WNRSBW', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A solid metal cube with side length $6$ cm is melted and recast into a rectangular prism with a square base of side length $4$ cm. What is the height, in centimeters, of the rectangular prism?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '13.5', ARRAY['27/2', '13.5'], E'The correct answer is $13.5$. The volume of the cube is $6^3 = 216$ cubic centimeters. Since the metal is recast, the volume is conserved. The rectangular prism has a square base with side $4$ cm, so its base area is $4^2 = 16$ square centimeters. Setting the volumes equal: $16h = 216$, which gives $h = \\frac{216}{16} = 13.5$. A common error is computing the cube volume as $6^2 = 36$ instead of $6^3 = 216$, leading to $h = \\frac{36}{16} = 2.25$. Another error is dividing by the base side length instead of the base area: $\\frac{216}{4} = 54$.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XDURTA', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{x^2 - 9}{x^2 - x - 6}$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{x + 3}{x + 2}$"},{"key":"B","text":"$\\frac{x - 3}{x - 2}$"},{"key":"C","text":"$\\frac{x + 3}{x - 2}$"},{"key":"D","text":"$\\frac{3}{2}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $\\frac{x + 3}{x + 2}$. Factor the numerator as a difference of squares: $x^2 - 9 = (x - 3)(x + 3)$. Factor the denominator: $x^2 - x - 6 = (x - 3)(x + 2)$. Cancel the common factor $(x - 3)$ to obtain $\\frac{x + 3}{x + 2}$. The expression $\\frac{x - 3}{x - 2}$ results from sign errors when factoring both the numerator and denominator. The expression $\\frac{x + 3}{x - 2}$ comes from incorrectly factoring the denominator as $(x - 3)(x - 2)$. The expression $\\frac{3}{2}$ results from incorrectly dividing the constant terms $\\frac{9}{6}$ rather than factoring.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XJUPEX', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'grid_in', E'The table below shows data for five observations.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XPNKFW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A bag contains $3$ red marbles, $5$ blue marbles, and $2$ green marbles. If one marble is selected at random, what is the probability that it is blue?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{1}{5}$"},{"key":"B","text":"$\\frac{3}{10}$"},{"key":"C","text":"$\\frac{1}{2}$"},{"key":"D","text":"$\\frac{1}{3}$"}]$lyceon_json$::jsonb, 'C', NULL, E'There are $3 + 5 + 2 = 10$ marbles total, and $5$ of them are blue, so the probability is $\\frac{5}{10} = \\frac{1}{2}$. The answer $\\frac{1}{5}$ results from incorrectly dividing the number of blue marbles by $25$ or miscomputing the total. The answer $\\frac{3}{10}$ comes from using the count of red marbles instead of blue marbles. The answer $\\frac{1}{3}$ results from assuming equal probability among the three colors rather than among the individual marbles.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XTVLJK', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'A circle has the equation $x^2 + y^2 - 6x + 4y - 12 = 0$. What is the radius of the circle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'The correct answer is $5$. Rewrite the equation by completing the square. Group the $x$-terms: $x^2 - 6x + 9 = (x - 3)^2$. Group the $y$-terms: $y^2 + 4y + 4 = (y + 2)^2$. Adding $9$ and $4$ to both sides of the equation gives $(x - 3)^2 + (y + 2)^2 = 12 + 9 + 4 = 25$. Since the standard form is $(x - h)^2 + (y - k)^2 = r^2$, we have $r^2 = 25$, so $r = 5$. A common error is adding only one completing-the-square constant, yielding $r^2 = 21$ or $r^2 = 16$ and an incorrect radius. Another error is reporting $r^2 = 25$ as the radius instead of taking the square root.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y7YBYT', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is one solution to the equation $x^2 - 5x + 6 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$1$"},{"key":"B","text":"$2$"},{"key":"C","text":"$-2$"},{"key":"D","text":"$6$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $2$. Factor the quadratic: $x^2 - 5x + 6 = (x - 2)(x - 3) = 0$, so $x = 2$ or $x = 3$. The value $1$ does not satisfy the equation since $1 - 5 + 6 = 2 \\neq 0$. The value $-2$ results from a sign error when reading the factors. The value $6$ comes from using the constant term of the equation rather than solving for $x$.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YIP2I8', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle has center $(3, -2)$ and passes through the point $(7, 1)$. What is the length of the radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$\\sqrt{7}$"},{"key":"B","text":"$5$"},{"key":"C","text":"$7$"},{"key":"D","text":"$25$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $5$. The radius equals the distance from the center to the point on the circle: $r = \\sqrt{(7-3)^2 + (1-(-2))^2} = \\sqrt{16 + 9} = \\sqrt{25} = 5$. The result $\\sqrt{7}$ comes from adding the absolute differences $|7-3| + |1+2| = 4 + 3 = 7$ and then taking the square root, instead of squaring each difference first. The result $7$ comes from summing the coordinate differences $4 + 3 = 7$ without applying the distance formula. The result $25$ comes from computing $r^2 = 25$ but reporting the squared value instead of taking the square root.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z5C283', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'grid_in', E'Line $p$ has the equation $x + 2y = 6$. Line $q$ is perpendicular to line $p$ and passes through the point $(3, 1)$. What is the $y$-intercept of line $q$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-5', ARRAY['-5'], E'Rewriting $x + 2y = 6$ in slope-intercept form gives $y = -\\frac{1}{2}x + 3$, so the slope of line $p$ is $-\\frac{1}{2}$. A line perpendicular to line $p$ has a slope that is the negative reciprocal, which is $2$. Using point-slope form with slope $2$ and the point $(3, 1)$: $y - 1 = 2(x - 3)$, which simplifies to $y = 2x - 6 + 1 = 2x - 5$. The $y$-intercept is $-5$.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z7HLQG', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'grid_in', E'The equation $3(2x - 5) + 4 = 2(x + 3) - 1$ has exactly one solution. What is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Distributing on the left side gives $6x - 15 + 4 = 6x - 11$. Distributing on the right side gives $2x + 6 - 1 = 2x + 5$. The equation becomes $6x - 11 = 2x + 5$. Subtracting $2x$ from both sides gives $4x - 11 = 5$. Adding $11$ to both sides gives $4x = 16$. Dividing both sides by $4$ gives $x = 4$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z9ZXVL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A pharmaceutical company wants to test whether a new drug reduces headache duration. They randomly assign $200$ participants to two groups: one receives the drug and the other receives a placebo. Neither the participants nor the researchers know who receives which treatment. Which feature of this study design helps establish a cause-and-effect relationship between the drug and headache duration?', NULL, $lyceon_json$[{"key":"A","text":"Using exactly $200$ participants"},{"key":"B","text":"Randomly assigning participants to treatment groups"},{"key":"C","text":"Conducting the study at a single location"},{"key":"D","text":"Measuring headache duration in minutes"}]$lyceon_json$::jsonb, 'B', NULL, E'Random assignment of participants to treatment and control groups is the key feature that allows a study to establish causation. It ensures that, on average, the groups are comparable in all respects other than the treatment, so any observed difference in outcomes can be attributed to the drug. A sample size of $200$ affects precision but does not by itself enable causal inference. Conducting the study at a single location is a logistical detail that does not determine whether causation can be established. Measuring headache duration in minutes is a choice of unit for the outcome variable, not a design feature that supports causal claims.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW218GIPF', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'When the committee announced its decision, neither the project manager nor the engineers ______ surprised by the outcome, as internal reports had already signaled the likely result weeks earlier.', $lyceon_json$[{"key":"A","text":"were"},{"key":"B","text":"was"},{"key":"C","text":"been"},{"key":"D","text":"being"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice is "were." In a "neither...nor" construction, the verb agrees with the subject closer to it — in this case, "engineers," which is plural. Therefore the plural verb "were" is required. The choice "was" incorrectly uses a singular verb, perhaps from agreeing with "project manager" or from treating "neither...nor" as inherently singular. The choice "been" is a past participle that lacks an auxiliary verb (such as "had"), producing an ungrammatical construction. The choice "being" is a present participle that cannot function as the main verb of the clause, leaving the sentence without a properly formed predicate.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22P80Z7', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'By the time the archaeological team completed its excavation of the site last autumn, the researchers ______ more than three thousand artifacts, including pottery fragments, bronze tools, and the remains of what appeared to be an ancient irrigation system.', $lyceon_json$[{"key":"A","text":"had cataloged"},{"key":"B","text":"have cataloged"},{"key":"C","text":"cataloged"},{"key":"D","text":"were cataloging"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice is "had cataloged." The construction "by the time [past event]" signals that one past action (cataloging) was completed before another past action (completing the excavation). This sequence requires the past perfect tense ("had cataloged") for the earlier action. The choice "have cataloged" uses the present perfect, which connects a past action to the present moment — inappropriate here because both events occurred entirely in the past ("last autumn"). The choice "cataloged" uses the simple past, which fails to establish the temporal ordering between the two past events; "by the time" specifically requires the past perfect to indicate which action came first. The choice "were cataloging" uses the past progressive, implying the cataloging was still in progress, but the definite count of "more than three thousand artifacts" indicates a completed tally, not an ongoing process.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
