INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW263VVLY', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall purpose of the passage?', E'Although the term "smartphone" was not widely used until the late 2000s, devices combining telephone and computing capabilities appeared as early as 1994. IBM''s Simon Personal Communicator, for instance, featured a touchscreen, email functionality, and third-party applications — features that would not become standard in mobile phones for over a decade. Despite its technical sophistication, the Simon sold poorly, in part because consumers at the time had little framework for understanding what such a device could offer them.', $lyceon_json$[{"key":"A","text":"To argue that IBM deserves more recognition for its contributions to smartphone development"},{"key":"B","text":"To compare the technological capabilities of early and modern smartphones"},{"key":"C","text":"To criticize consumers for failing to recognize the value of innovative technology"},{"key":"D","text":"To explain why a technologically advanced device failed to achieve commercial success"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct answer is the choice about explaining why a technologically advanced device failed commercially. The passage describes the Simon''s impressive features and then accounts for its poor sales by noting that consumers lacked a framework for understanding its utility. The choice about IBM deserving more recognition overstates the passage''s purpose: the passage describes the Simon''s history but does not argue for credit or recognition. The choice about comparing early and modern smartphones is unsupported because the passage does not describe modern smartphone capabilities in any detail. The choice about criticizing consumers mischaracterizes the passage''s neutral, explanatory tone as judgmental.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27CMX3U', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Elena Martinez, a celebrated architect ______ designed the city''s new performing arts center, drawing praise from both critics and residents for its innovative use of natural light and reclaimed materials.', $lyceon_json$[{"key":"A","text":", designed"},{"key":"B","text":". Designed"},{"key":"C","text":"; designed"},{"key":"D","text":"— designed"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice is the one that places a comma after "architect" (", designed"). The phrase "a celebrated architect" is a nonrestrictive appositive renaming "Elena Martinez," and since the appositive is introduced with a comma, it must be closed with a matching comma before the main verb "designed." The choice using a period ("Designed") creates a sentence fragment because "Designed the city''s new performing arts center" lacks a subject. The choice using a semicolon incorrectly treats what follows as an independent clause, but "designed the city''s new performing arts center" is not an independent clause — it is the main predicate of the sentence. The choice using a dash creates mismatched punctuation: the appositive opens with a comma, so it cannot close with a dash.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29OXAAY', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'During the late nineteenth century, the French chemist Henri Moissan claimed to have synthesized diamonds by rapidly cooling molten iron saturated with carbon. His announcement generated enormous excitement, and several laboratories attempted to replicate the process. None succeeded, and modern analyses of Moissan''s original samples suggest they were likely natural diamonds inadvertently introduced during the experiments. ______ Moissan''s work was not entirely without value: his high-pressure techniques later informed the development of methods that did produce synthetic diamonds in the 1950s.', $lyceon_json$[{"key":"A","text":"Moreover,"},{"key":"B","text":"That said,"},{"key":"C","text":"For this reason,"},{"key":"D","text":"Specifically,"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct transition is "That said," because the passage first establishes that Moissan''s diamond synthesis was discredited — replication failed and the samples were likely natural diamonds — but then concedes that his work still had indirect value. "That said," appropriately introduces a concession that qualifies the preceding negative assessment. "Moreover," would add a point that reinforces the preceding idea, but the final sentence shifts from failure to partial vindication. "For this reason," would indicate that the value of Moissan''s work resulted from the failed replications, which misrepresents the logical relationship. "Specifically," would narrow or elaborate on the preceding claim, but the sentence introduces a separate, contrasting point about the legacy of the work.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29XZJXF', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The decision to relocate the company''s headquarters, along with the announcement that several regional offices would be consolidated into larger facilities in neighboring cities, ______ anxiety among employees who feared that their positions might be eliminated during the restructuring process.', $lyceon_json$[{"key":"A","text":"generated"},{"key":"B","text":"have generated"},{"key":"C","text":"were generating"},{"key":"D","text":"generate"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice is "generated." The subject of the sentence is "decision," which is singular. The phrase "along with the announcement that several regional offices would be consolidated into larger facilities in neighboring cities" is a parenthetical addition — unlike "and," the phrase "along with" does not create a compound subject. The verb must therefore be singular and in the past tense to match the past-tense context established by "would be consolidated" and "feared." The choice "have generated" uses a plural auxiliary, incorrectly treating the parenthetical as a compound subject. The choice "were generating" is both plural and in the past progressive, committing the same agreement error while also implying an ongoing action without contextual support. The choice "generate" is plural and in the present tense, mismatching both the singular subject and the past time frame of the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29YQ4SW', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Marine biologists studying coral reefs in the Pacific Ocean have documented a sharp decline in reef coverage over the past two decades. According to their surveys, living coral now covers approximately 30 percent of reef structures that were once fully covered. The researchers attribute this decline primarily to rising ocean temperatures, which cause coral bleaching—a process in which stressed corals expel the symbiotic algae that provide them with nutrients and color.', $lyceon_json$[{"key":"A","text":"Coral reefs in the Pacific Ocean have experienced significant decline due to rising ocean temperatures."},{"key":"B","text":"Marine biologists have developed new techniques for surveying coral reef populations."},{"key":"C","text":"Symbiotic algae are essential to the survival of all marine organisms in reef ecosystems."},{"key":"D","text":"Ocean temperatures in the Pacific have remained stable over the past two decades."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on the documented decline of coral reef coverage in the Pacific, attributing it to rising ocean temperatures that cause coral bleaching. The choice stating that coral reefs have experienced significant decline due to rising ocean temperatures captures this central point. The choice about new surveying techniques is unsupported—the passage mentions surveys but says nothing about new methods. The choice claiming symbiotic algae are essential to all marine organisms overgeneralizes; the passage discusses algae only in relation to corals. The choice suggesting stable ocean temperatures directly contradicts the passage''s statement about rising temperatures.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2A8XMLY', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of rare manuscripts housed in the university''s archive ______ a valuable resource for scholars studying medieval European history and literature.', $lyceon_json$[{"key":"A","text":"remains"},{"key":"B","text":"remain"},{"key":"C","text":"remaining"},{"key":"D","text":"have remained"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice is "remains." The subject of the sentence is "collection," which is singular, so the verb must also be singular. The prepositional phrase "of rare manuscripts housed in the university''s archive" modifies "collection" but does not change the subject''s number. The choice "remain" incorrectly uses a plural verb, likely from mistaking the nearer noun "manuscripts" for the subject. The choice "remaining" is a participle, not a finite verb, and would leave the sentence without a main verb, creating a fragment. The choice "have remained" uses a plural auxiliary verb, committing the same agreement error as "remain" while also shifting to present perfect tense without justification from the context.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2C5RKUI', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the passage, "crude" most nearly means', E'Art critics initially dismissed the painter''s early canvases as technically deficient, noting that her brushwork appeared hurried and her compositions lacked balance. However, later scholars have argued that these supposedly crude elements were deliberate choices that gave the works an emotional immediacy absent from more polished paintings of the era.', $lyceon_json$[{"key":"A","text":"unrefined"},{"key":"B","text":"offensive"},{"key":"C","text":"fraudulent"},{"key":"D","text":"abundant"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is "unrefined." The passage describes brushwork that appeared hurried and compositions that lacked balance, characterizing technical roughness and lack of polish. "Unrefined" captures this sense of lacking sophistication in execution. "Offensive" means causing displeasure or insult, but the passage discusses artistic technique, not moral objectionability. "Fraudulent" means deceptive or fake, which contradicts the passage''s point that the elements were genuine artistic choices. "Abundant" means plentiful, which has no connection to the quality or polish of the brushwork described.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CHP3WG', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the last sentence in the passage?', E'Historian Elaine Forrest has challenged the prevailing narrative that the construction of the transcontinental railroad was driven primarily by economic motives. While acknowledging that commercial interests played a role, Forrest contends that political leaders advocated for the railroad chiefly as a means of binding together a geographically fragmented nation in the aftermath of the Civil War. She points to congressional debates from the 1860s in which senators invoked the language of national unity far more frequently than they discussed projected freight revenues or trade routes.', $lyceon_json$[{"key":"A","text":"It identifies a limitation in the methodology Forrest used to develop her argument."},{"key":"B","text":"It summarizes the economic arguments that Forrest's research seeks to refute."},{"key":"C","text":"It provides evidence supporting Forrest's interpretation of the railroad's primary purpose."},{"key":"D","text":"It presents a counterexample that complicates Forrest's thesis about the railroad."}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is the choice stating that the last sentence provides evidence supporting Forrest''s interpretation. The final sentence cites congressional debates in which senators emphasized national unity over economic concerns, directly substantiating Forrest''s claim that political unity, not commerce, was the primary motive. The choice about a methodological limitation is wrong because the sentence presents evidence in favor of Forrest''s argument, not a weakness in her approach. The choice about summarizing economic arguments misreads the sentence: it describes what senators did not emphasize (freight revenues and trade routes) to support a political-unity reading, rather than presenting the economic case. The choice about a counterexample is wrong because the evidence aligns with, rather than complicates, Forrest''s thesis.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2D7D656', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Historian Lena Cowen Orlin has challenged the long-held assumption that early modern English households maintained strict separations between domestic and commercial spaces. Examining architectural records, household inventories, and legal documents from sixteenth-century London, Orlin found that rooms designated in building plans as parlors or bedchambers frequently contained tools, raw materials, and merchant ledgers. Moreover, servants'' testimonies in court cases reveal that family meals often took place in the same rooms where goods were stored and transactions conducted. Orlin''s findings therefore suggest that ________', $lyceon_json$[{"key":"A","text":"the spatial boundaries between private life and economic activity in early modern English homes were far more fluid than scholars had previously believed."},{"key":"B","text":"sixteenth-century London merchants deliberately concealed their commercial activities from public authorities by conducting business in private rooms."},{"key":"C","text":"architectural records from sixteenth-century London are unreliable sources for understanding how domestic spaces were actually used."},{"key":"D","text":"the separation of home and workplace that characterizes modern Western societies was already well established by the sixteenth century."}]$lyceon_json$::jsonb, 'A', NULL, E'Orlin''s evidence shows that rooms designated for domestic use contained commercial items and that family activities occurred in spaces used for business, directly challenging the assumption of strict spatial separation. The logical conclusion is that the boundaries between private life and economic activity were more fluid than previously believed. The choice about merchants deliberately concealing commercial activities introduces a motive (deception of authorities) that the passage never suggests; Orlin presents the blending of spaces as ordinary practice, not secretive behavior. The choice calling architectural records unreliable misreads Orlin''s argument; she uses the discrepancy between building plans and actual use as evidence of fluid boundaries, not as grounds to dismiss the records themselves. The choice stating the home-workplace separation was already established directly contradicts Orlin''s central finding that such separation did not exist in sixteenth-century London households.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EDCYXA', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The novelist Toni Morrison, whose works explore themes of identity and historical memory ______ received the Nobel Prize in Literature in 1993, becoming the first African American woman to be honored with the award.', $lyceon_json$[{"key":"A","text":", received"},{"key":"B","text":"; received"},{"key":"C","text":", she received"},{"key":"D","text":"received"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice is ", received." The sentence''s main subject is "The novelist Toni Morrison," and "whose works explore themes of identity and historical memory" is a nonrestrictive clause that interrupts the main clause. A comma is required after "memory" to close this nonrestrictive clause and allow the main verb "received" to continue the sentence. The choice using a semicolon ("received" after a semicolon) is wrong because a semicolon requires an independent clause on each side, but "received the Nobel Prize..." is not an independent clause here — it is the predicate of the main clause whose subject is "Toni Morrison." The choice inserting "she received" after a comma introduces a redundant subject pronoun, creating a grammatically faulty structure in which "Toni Morrison" and "she" compete as the subject. The choice omitting the comma entirely ("memory received") fails to close the nonrestrictive "whose" clause, fusing it into the predicate and making the sentence structurally ungrammatical.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EEVT1O', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'Economists have long debated whether minimum wage increases reduce employment among low-wage workers. A 2019 study by Cengiz, Dube, Lindner, and Zipperer analyzed 138 state-level minimum wage changes in the United States between 1979 and 2016. The researchers found that while the number of jobs paying below the new minimum wage decreased sharply after each increase, the total number of low-wage jobs remained essentially unchanged. This pattern suggests that minimum wage increases redistribute workers from below-minimum to at-or-above-minimum pay tiers rather than eliminating positions, though the researchers acknowledged that effects may differ in regions with unusually high minimum-to-median wage ratios.', $lyceon_json$[{"key":"A","text":"A large-scale study found that minimum wage increases generally shifted workers to higher pay tiers without reducing overall low-wage employment, though regional variation may exist."},{"key":"B","text":"Minimum wage increases consistently eliminate low-wage jobs, according to a comprehensive analysis of state-level data."},{"key":"C","text":"The 2019 study conclusively resolved the longstanding economic debate about the employment effects of minimum wage increases."},{"key":"D","text":"Regions with high minimum-to-median wage ratios experience the same employment effects as other regions when minimum wages rise."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a study finding that minimum wage increases redistributed workers to higher pay tiers without reducing overall low-wage employment, while noting a caveat about regions with high minimum-to-median wage ratios. The choice mentioning the shift to higher pay tiers without reduced employment and acknowledging regional variation captures both the finding and the qualification. The choice claiming minimum wage increases consistently eliminate low-wage jobs contradicts the study''s central finding that total low-wage jobs remained essentially unchanged. The choice stating the study conclusively resolved the debate overstates its impact; the passage frames it as a contribution to an ongoing debate and notes a limitation. The choice asserting that high-ratio regions experience the same effects contradicts the researchers'' acknowledgment that effects may differ in such regions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EFNQQ5', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the passage, "compromise" most nearly means', E'The restoration of the sixteenth-century fresco required the conservators to address not only the visible damage caused by centuries of exposure to moisture but also the more insidious threat posed by salts that had migrated deep into the plaster substrate. Left unchecked, these crystalline deposits would continue to compromise the structural cohesion of the wall itself, eventually causing the painted surface to detach in large, irreparable sections.', $lyceon_json$[{"key":"A","text":"negotiate"},{"key":"B","text":"undermine"},{"key":"C","text":"reveal"},{"key":"D","text":"stabilize"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is "undermine." The passage describes crystalline salt deposits that threaten the wall''s structural cohesion, eventually causing the painted surface to detach. In this context, "compromise" means to weaken or damage gradually, which "undermine" captures precisely. "Negotiate" means to discuss terms in order to reach an agreement, which is incoherent when applied to salt deposits acting upon a wall''s structure. "Reveal" means to make visible or known, but the deposits are not exposing the cohesion — they are destroying it. "Stabilize" means to make steady or firm, which is the opposite of what the passage describes: the deposits are degrading the wall, not reinforcing it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FDETLR', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'In a 2023 study, marine biologists at the Monterey Bay Aquarium Research Institute observed that certain species of deep-sea jellyfish produce bioluminescent flashes when physically disturbed by predators. The researchers initially hypothesized that this light display served as a warning signal to deter attacks. ______ subsequent experiments revealed that the flashes actually attract larger predators to the area, which then prey upon the jellyfish''s attackers — a defense strategy known as the "burglar alarm" effect.', $lyceon_json$[{"key":"A","text":"For instance,"},{"key":"B","text":"However,"},{"key":"C","text":"In addition,"},{"key":"D","text":"Accordingly,"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct transition is "However," because the passage presents a contrast between the researchers'' initial hypothesis (that bioluminescence deters predators) and what experiments actually showed (that it attracts larger predators to attack the jellyfish''s attackers). "For instance," would introduce an example supporting the hypothesis, but the sentence that follows contradicts it. "In addition," implies the next finding supplements the hypothesis, when it actually overturns it. "Accordingly," suggests the experimental results followed logically from the hypothesis, but the findings contradicted the original expectation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GJCYBZ', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Recent archaeological discoveries in southern Mexico suggest that the ancient Olmec civilization ______ which flourished between 1500 and 400 BCE, developed a writing system far earlier than researchers had previously believed.', $lyceon_json$[{"key":"A","text":", which flourished"},{"key":"B","text":"which flourished"},{"key":"C","text":". Which flourished"},{"key":"D","text":"; which flourished"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice is ", which flourished." The clause "which flourished between 1500 and 400 BCE" is nonrestrictive — it provides additional information about the Olmec civilization, which is already specifically identified. Nonrestrictive clauses must be set off by commas. The choice omitting the comma ("which flourished") fails to punctuate the nonrestrictive clause, treating it as restrictive and implying there were multiple Olmec civilizations, only one of which flourished in that period. The choice using a period (". Which flourished") creates a sentence fragment, since "Which flourished between 1500 and 400 BCE" is a dependent clause and cannot stand alone as a sentence. The choice using a semicolon incorrectly treats the dependent "which" clause as an independent clause; semicolons may only join independent clauses.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JTOT9K', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'While writing about the architect Zaha Hadid for an audience unfamiliar with contemporary architecture, a student wants to introduce Hadid''s significance by connecting her design philosophy to a specific achievement. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NZ7CNN', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the passage, "conserve" most nearly means', E'A scientist studying desert ecosystems noted that certain lizard species have developed remarkable adaptations to conserve water. Their skin, for instance, is virtually impermeable, preventing moisture from escaping even during the hottest hours of the day. These physiological traits allow the lizards to thrive in environments where most other vertebrates would quickly succumb to dehydration.', $lyceon_json$[{"key":"A","text":"generate"},{"key":"B","text":"monitor"},{"key":"C","text":"retain"},{"key":"D","text":"distribute"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is "retain." The passage describes lizards that have adaptations to conserve water, meaning they keep or hold onto it rather than losing it through their skin. The passage reinforces this by noting that the skin prevents moisture from escaping. "Generate" means to produce or create, which is wrong because the lizards are not creating water but preventing its loss. "Monitor" means to observe or track, which describes a passive action unrelated to preventing water loss. "Distribute" means to spread out or allocate, which is the opposite of keeping water within the body.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Q3L06I', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'While writing an article about urban beekeeping, a student wants to emphasize the environmental benefit of the practice. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QG8EXR', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Professor Liu, who has spent decades researching renewable energy sources, argues that solar power, despite its current limitations ______ will become the dominant source of electricity worldwide by 2050.', $lyceon_json$[{"key":"A","text":", will become"},{"key":"B","text":". Will become"},{"key":"C","text":"; will become"},{"key":"D","text":"will become"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice is ", will become." The sentence contains multiple layers of embedded structure: the main clause ("Professor Liu argues that solar power will become...") is interrupted by a nonrestrictive "who" clause and a parenthetical phrase "despite its current limitations." This parenthetical phrase, introduced with a comma after "power," must be closed with a matching comma before "will become" to restore the grammatical flow of the "that" clause. The choice using a period (". Will become") creates a sentence fragment because "Will become the dominant source of electricity worldwide by 2050" has no subject. The choice using a semicolon incorrectly treats "will become the dominant source..." as an independent clause, but it is the predicate of the embedded "that" clause and has no independent subject. The choice omitting the comma ("limitations will become") leaves the parenthetical phrase unclosed, breaking the parallel punctuation that the opening comma established and creating a structural error.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QG8KHF', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Archaeologists excavating a Bronze Age settlement in southeastern Turkey uncovered a collection of clay tablets inscribed with an unknown script. The symbols bore no resemblance to Sumerian cuneiform or Egyptian hieroglyphics, leading some scholars to propose that the tablets represented an entirely independent writing system. ______ closer analysis of the tablet fragments showed that the symbols were systematic variations of Luwian hieroglyphs — a script already documented in the region — that had been adapted for recording commercial transactions rather than royal decrees.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"Furthermore,"},{"key":"C","text":"As a result,"},{"key":"D","text":"Upon further review,"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct transition is "Upon further review," because the passage moves from an initial scholarly interpretation (an entirely independent writing system) to a corrected understanding reached through more detailed analysis (the symbols were adapted Luwian hieroglyphs). This transition signals that additional investigation revised the earlier conclusion. "In other words," would restate the same claim in different terms, but the second sentence presents a different finding, not a rephrasing. "Furthermore," would add supporting evidence to the initial proposal, yet the subsequent analysis contradicts that proposal. "As a result," implies the closer analysis was a consequence of the initial proposal, but the passage presents a correction of the earlier interpretation rather than a causal outcome.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
