INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2R07DC4', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a research article would most effectively support the claim that sleep deprivation impairs decision-making abilities?', E'Neuroscientists have argued that chronic sleep deprivation compromises the prefrontal cortex, the brain region most associated with executive functions such as planning, judgment, and impulse control. Some researchers contend that even moderate sleep loss—defined as sleeping fewer than six hours per night for a week—can produce measurable cognitive deficits comparable to those observed after 24 hours of total sleep deprivation.', $lyceon_json$[{"key":"A","text":"\"Participants who slept fewer than six hours per night for five consecutive nights showed a 40 percent increase in errors on tasks requiring risk assessment and cost-benefit analysis.\""},{"key":"B","text":"\"Individuals who reported sleeping nine or more hours per night performed no differently on cognitive tests than those sleeping seven hours.\""},{"key":"C","text":"\"Sleep deprivation was associated with increased activity in the amygdala, suggesting heightened emotional reactivity.\""},{"key":"D","text":"\"Participants who napped for 20 minutes in the afternoon demonstrated improved reaction times on simple motor tasks.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The claim is that sleep deprivation impairs decision-making abilities. The quotation about a 40 percent increase in errors on risk assessment and cost-benefit analysis tasks after limited sleep directly links sleep deprivation to measurable decision-making deficits. The quotation about oversleeping and cognitive tests addresses excess sleep, not deprivation, and thus does not support the claim. The quotation about amygdala activity and emotional reactivity relates to emotional processing rather than decision-making, addressing a different cognitive domain. The quotation about napping and reaction times concerns sleep recovery and motor performance, neither of which connects to the claim about impaired decision-making from sleep deprivation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RXGWFZ', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'The city of Valencia, Spain, has long been known for its elaborate annual festival, Las Fallas, which features enormous sculptural installations made of papier-mâché and wood. Each year, artisans spend months constructing these towering figures, some reaching over fifteen meters in height. ______ on the final night of the festival, the sculptures are set ablaze in a spectacular display of fire and celebration.', $lyceon_json$[{"key":"A","text":"Then,"},{"key":"B","text":"In contrast,"},{"key":"C","text":"Similarly,"},{"key":"D","text":"Nevertheless,"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct transition is "Then," because the passage describes a chronological sequence: artisans spend months building the sculptures, and afterward, on the final night, the sculptures are burned. "In contrast," wrongly signals opposition between two ideas that are part of the same sequential process. "Similarly," incorrectly implies that the burning is comparable to another event, when no comparison is being made. "Nevertheless," implies the burning happened despite some obstacle, but nothing in the passage suggests the burning was unexpected or contrary to expectation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SNQTL5', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'In the 1950s, psychologist Solomon Asch conducted experiments in which participants were asked to match the length of a line to one of three comparison lines—a task with an obvious correct answer. When confederates in the group unanimously chose the wrong line, approximately 75 percent of participants conformed to the incorrect majority answer at least once. However, when even a single confederate broke from the majority and selected the correct line, conformity rates dropped dramatically. These results imply that ________', $lyceon_json$[{"key":"A","text":"the presence of even one dissenting voice can substantially reduce an individual's tendency to conform to group pressure."},{"key":"B","text":"most people are unable to identify the correct answer in perceptual tasks without guidance from others."},{"key":"C","text":"participants in Asch's experiments were primarily motivated by a desire to avoid conflict with the confederates."},{"key":"D","text":"conformity is a behavior observed only in laboratory settings and does not occur in real-world social situations."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that conformity rates dropped dramatically when a single confederate selected the correct line, directly implying that one dissenting voice substantially reduces conformity to group pressure. The choice about people being unable to identify correct answers contradicts the passage, which describes the task as having an obvious correct answer. The choice about participants being motivated by conflict avoidance introduces a specific psychological motive the passage does not address; the passage describes the conformity behavior but does not explain its cause. The choice limiting conformity to laboratory settings makes an unsupported claim the passage never suggests; the passage describes a lab study but draws no conclusions about whether conformity occurs elsewhere.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2U0GXDM', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the overall structure of the passage?', E'The Venus flytrap is one of the few plants capable of rapid movement. When an insect lands on one of its hinged leaves and touches the tiny trigger hairs inside, the leaf snaps shut in less than a second. Digestive enzymes then break down the captured prey, providing the plant with nutrients that are scarce in its native boggy habitat.', $lyceon_json$[{"key":"A","text":"It introduces a natural phenomenon and then explains the process by which it occurs."},{"key":"B","text":"It presents a scientific debate and then offers a resolution."},{"key":"C","text":"It describes an experiment and then reports the results."},{"key":"D","text":"It proposes a hypothesis and then provides evidence that contradicts it."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that the passage introduces a natural phenomenon and explains the process by which it occurs. The passage opens by identifying the Venus flytrap''s unusual capability, then walks through the step-by-step mechanism of trapping and digesting prey. The choice describing a scientific debate is wrong because the passage presents no competing viewpoints. The choice describing an experiment is wrong because the passage describes a natural process, not a controlled study. The choice about a contradicted hypothesis is wrong because no hypothesis is proposed or challenged in the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UJQ7GY', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'In the early twentieth century, the prevailing view among linguists was that signed languages used by deaf communities were merely gestural codes—simplified versions of spoken languages lacking true grammatical structure. This assumption went largely unchallenged until William Stokoe, a professor at Gallaudet University, published his 1960 analysis of American Sign Language. Stokoe demonstrated that ASL possesses its own phonological system, morphology, and syntax, operating independently of English. His work prompted a fundamental reassessment of what constitutes a language and opened the field of sign language linguistics.', $lyceon_json$[{"key":"A","text":"Stokoe's research revealed that ASL has its own complete grammatical structure, overturning earlier assumptions about signed languages."},{"key":"B","text":"Deaf communities in the early twentieth century developed ASL as a replacement for spoken English."},{"key":"C","text":"Linguists in the early twentieth century studied signed languages extensively but reached no conclusions about their structure."},{"key":"D","text":"Stokoe's primary contribution was demonstrating that ASL's phonological system is identical to that of English."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how earlier linguists dismissed signed languages as lacking grammar, and how Stokoe''s 1960 analysis proved ASL has independent phonological, morphological, and syntactic systems. The choice about Stokoe revealing ASL''s complete grammatical structure and overturning earlier assumptions captures this arc. The choice about deaf communities developing ASL as a replacement for English is unsupported; the passage does not discuss ASL''s origins. The choice claiming linguists studied signed languages extensively but reached no conclusions contradicts the passage, which says the prevailing view was that signed languages lacked grammar. The choice stating Stokoe showed ASL''s phonology is identical to English''s contradicts the passage''s explicit statement that ASL operates independently of English.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VIC6CT', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding, if true, would most directly weaken the researchers'' conclusion?', E'A 2021 study examined whether urban green spaces reduce stress levels in city residents. Researchers measured cortisol levels—a hormonal marker of stress—in 500 participants before and after 30-minute visits to urban parks. They found that average cortisol levels dropped by 15 percent after the park visits and concluded that exposure to urban green spaces directly reduces physiological stress. The study controlled for time of day and physical activity levels during the visits.', $lyceon_json$[{"key":"A","text":"Participants who spent 30 minutes sitting quietly in indoor waiting rooms showed a comparable 14 percent decrease in cortisol levels."},{"key":"B","text":"Cortisol levels in the study participants returned to baseline within two hours of leaving the parks."},{"key":"C","text":"Participants who visited parks with more tree coverage experienced slightly larger cortisol reductions than those in open-lawn parks."},{"key":"D","text":"A separate study found that residents who live near parks report lower overall stress levels than those who do not."}]$lyceon_json$::jsonb, 'A', NULL, E'The researchers concluded that exposure to urban green spaces directly reduces physiological stress. The finding that sitting quietly indoors produced a comparable cortisol reduction would weaken this conclusion by suggesting the decrease results from rest or inactivity rather than the green space itself, undermining the causal link to nature exposure. The finding that cortisol returned to baseline after two hours addresses the duration of the effect but does not challenge whether green spaces caused the initial reduction. The finding about tree coverage producing larger reductions would actually strengthen the conclusion by suggesting a dose-response relationship with nature exposure. The finding that park-adjacent residents report lower stress levels is correlational and addresses a different population, so it neither strengthens nor weakens the specific causal claim in the study.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XJ1T4Q', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'A team of ornithologists hypothesized that migratory songbirds select stopover sites during long flights based primarily on the availability of insect prey rather than on vegetation density or proximity to water sources. To test this hypothesis, the researchers planned to compare bird counts at various sites along the Atlantic flyway during the fall migration season.', $lyceon_json$[{"key":"A","text":"Sites with the highest insect abundance consistently attracted the greatest number of migratory songbirds, regardless of vegetation density."},{"key":"B","text":"Migratory songbirds were observed at stopover sites in roughly equal numbers across all locations surveyed."},{"key":"C","text":"Sites with dense vegetation attracted the most migratory songbirds, even when insect populations were low."},{"key":"D","text":"Songbirds that migrated shorter distances did not use stopover sites at all."}]$lyceon_json$::jsonb, 'A', NULL, E'The researchers hypothesized that insect prey availability is the primary factor in stopover site selection. The finding that sites with the highest insect abundance attracted the most birds regardless of vegetation density directly supports this claim by showing insect availability predicts bird presence while vegetation density does not. The finding of roughly equal numbers across all sites would suggest no factor drives site selection, which neither supports nor refutes the hypothesis. The finding that dense vegetation attracted the most birds even with low insect populations would undermine the hypothesis by suggesting vegetation matters more. The finding about shorter-distance migrants not using stopover sites is irrelevant to the hypothesis about what drives site selection among birds that do stop.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZCTD0N', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The Arctic fox is one of the few mammals that changes the color of its fur with the seasons. In winter, its coat turns white, providing camouflage against the snow-covered landscape. In summer, the fur shifts to brown or gray, blending with the tundra''s exposed rocks and soil. This seasonal adaptation suggests that the Arctic fox''s survival depends heavily on ________', $lyceon_json$[{"key":"A","text":"its ability to avoid detection by predators and prey across changing environments."},{"key":"B","text":"its capacity to tolerate extreme cold temperatures throughout the year."},{"key":"C","text":"the availability of food sources during the winter months specifically."},{"key":"D","text":"its social behavior and cooperative hunting strategies with other foxes."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how the Arctic fox changes fur color seasonally to blend with its surroundings in both winter and summer. The logical inference is that this camouflage adaptation indicates survival depends on avoiding detection across changing environments, since both color shifts serve concealment. The choice about tolerating extreme cold is unrelated to fur color change; the passage discusses camouflage, not thermoregulation. The choice about winter food availability addresses only one season and ignores that the passage emphasizes camouflage in both seasons. The choice about social behavior and cooperative hunting is entirely unsupported; the passage mentions no social dynamics.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-15"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-15","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
